methods.body:
if (this.replaying) return this.played(chip)
this.cycles = this.cycles + 97
return noiseAfter(this.cycles + (chip == 2 ? 65536 : 0))

return { id, inPlay: false, kind: "flipper", depth: 0, depthFraction: 0, lane: 0, flipping: false,
    angle: 0, turning: "cw", rising: true, cargo: "none", fires: false, fireWait: 0, resting: false,
    plan: "climb", count: 0 }

if (this.wellSetUp) return
if (this.screen == "play" && this.flashing) this.bonusFlash = this.bonusFlash - 1
if (this.screen == "choose") this.choice = this.spinChoice(field, this.choice)

const was = this.pressed.includes(name)
this.pressed = this.pressed.filter((p) => p != name)
return was

if (!this.pauseSlowly || this.frame % 2 == 0) {
    if (this.pauseLeft > 0) this.pauseLeft = this.pauseLeft - 1
    if (this.pauseLeft == 0) { this.phase = this.next; this.pauseSlowly = false }
    }
this.moveClaw(field)

if (this.reached < 98) { this.reached = this.reached + 1; this.waveIndex = this.waveIndex + 1 }
this.phase = "arriving"
if (this.startBonus != 0) { this.addScore(this.startBonuses[this.startBonus] * 100); this.sound("bonus") }
this.newWave(field)

const claw = field.claw
if (!claw.alive) return
let t = 0
if (!this.playing) t = this.steer(field)
else { t = Math.max(-31, Math.min(31, this.turn)); this.turn = 0 }
const to = this.well.open ? Math.max(0, Math.min(0xef, claw.position - t)) : byte(claw.position - t)
if ((to >> 4) != claw.lane) this.sound("click")
claw.lane = to >> 4
claw.position = to

let nearest = 255, which = -1
for (let i = this.level.enemySlots - 1; i >= 0; i--) {
    const e = field.enemies[i]
    if (e.inPlay && e.depth < nearest) { nearest = e.depth; which = i }
    }
if (which < 0) return 0
const d = this.lanesBetween(field.claw.lane, field.enemies[which].lane)
return d == 0 ? 0 : d > 0 ? -9 : 9

const claw = field.claw
if (!claw.alive || !claw.dropping) return
if (claw.depth == RIM) this.sound("fallTube")
let p = claw.depth * 256 + claw.depthFraction + claw.fallSpeed
let out = p >= 65536
claw.depth = byte(p >> 8); claw.depthFraction = p & 255
if (out || claw.depth >= FAR) { this.phase = "waveDone"; claw.depth = 0xff; this.sound("fallSpace") }
if (claw.depth >= 0x50 && this.stars == "none") this.startStars(field)
const before = this.eyeDepth
this.eye = this.eye + claw.fallSpeed
if (this.eyeDepth != before) this.wellMoved = true
claw.fallSpeed = claw.fallSpeed + Math.min(byte(this.waveIndex * 4), 0x30) + 0x20     // (counted round: from wave 65 the fall begins again as slowly as wave 1's)
if (claw.depth < FAR) {
    const tip = field.spikes[claw.lane]
    if (tip != 0 && tip < claw.depth) {
        this.killClaw(field, "pulsar")
        this.stars = "none"
        for (const s of [...field.shots, ...field.enemyShots]) s.inPlay = false
        this.shotsFlying = 0; this.enemyShotsFlying = 0
        }
    }

for (let i = 3; i >= 0; i--) {
    const s = field.enemyShots[i]
    if (!s.inPlay) continue
    const p = word(s.depth * 256 + s.depthFraction + this.shotSpeed)
    s.depthFraction = byte(p)
    let depth = byte(p >> 8)
    if (depth < field.claw.depth) {
        this.enemyShotsFlying = this.enemyShotsFlying - 1
        this.shotReachesRim(field, s)
        depth = 0
        }
    s.depth = depth
    s.inPlay = depth != 0
    }
for (let i = 7; i >= 0; i--) {
    const s = field.shots[i]
    if (!s.inPlay) continue
    s.depth = byte(s.depth + 9 - (s.spikesHit != 0 ? 4 : 0))
    this.shotMeetsSpike(field, s)
    if (s.inPlay && s.depth >= FAR) { this.shotsFlying = this.shotsFlying - 1; s.inPlay = false; s.depth = 0 }
    }

const tip = field.spikes[s.lane]
if (tip != 0 && s.depth >= tip) {
    field.spikes[s.lane] = s.depth >= FAR ? 0 : s.depth
    s.spikesHit = s.spikesHit + 1
    field.spikeMarks[s.lane] = 3
    this.sound("spikeHit")
    this.addScore(1)
    }
if (s.spikesHit >= 2) { s.inPlay = false; s.depth = 0; this.shotsFlying = this.shotsFlying - 1 }

const s = field.shots[i]
const at = s.depth
for (let k = this.level.enemySlots - 1; k >= 0; k--) {
    const n = field.enemies[k]
    if (!n.inPlay) continue
    if (Math.abs(n.depth - at) >= this.ranges[n.kind]) continue
    if (n.kind == "fuseball") {
        if (n.depth != field.claw.depth && s.lane == n.lane && n.flipping) this.hitFuseball(field, s, n)
        }
    else if (n.flipping ? n.lane == s.nextLane || n.lane == s.lane : n.depth != field.claw.depth && n.lane == s.lane)
        this.hitEnemy(field, s, n)
    }
for (let k = 3; k >= 0; k--) {
    const e = field.enemyShots[k]
    if (e.inPlay && Math.abs(e.depth - at) < this.shotRange && e.lane == s.lane) this.shotsCollide(field, s, e)
    }
if (s.used) { s.inPlay = false; s.depth = 0; this.shotsFlying = this.shotsFlying - 1; s.used = false; s.spikesHit = 0 }

let slot = -1, most = -1, mostAt = 0
for (let i = 7; i >= 0; i--) {
    const b = field.blasts[i]
    if (!b.inPlay) { slot = i; break }
    if (b.stage >= most) { most = b.stage; mostAt = i }
    }
if (slot < 0) { this.blastsGoing = this.blastsGoing - 1; slot = mostAt }
field.blasts[slot] = { id: slot, inPlay: depth != 0, lane, depth, kind, stage: 0 }
this.blastsGoing = this.blastsGoing + 1

if (this.blastsGoing == 0) return
this.blastsGoing = 0
for (let i = 7; i >= 0; i--) {
    const b = field.blasts[i]
    if (!b.inPlay) continue
    b.stage = b.stage + this.blastGrowth[b.kind]
    if (b.stage >= this.blastEnd[b.kind]) { b.inPlay = false; b.depth = 0 }
    else this.blastsGoing = this.blastsGoing + 1
    }

const claw = field.claw
if (!claw.alive) {
    if (this.shotsFlying != 0 || this.enemyShotsFlying != 0 || this.blastsGoing != 0) return
    for (let i = this.level.enemySlots - 1; i >= 0; i--) {
        const e = field.enemies[i]
        if (!e.inPlay) continue
        const d = e.depth + 15
        e.depth = d >= FAR ? 0 : d
        e.inPlay = e.depth != 0
        }
    let done = false
    if (this.lives == 1) {
        this.wellMoved = true; this.eyeDrawsBack = true
        this.eye = this.eye - 0x20 * 256
        done = this.eyeDepth < -0x500
        }
    else {
        const d = claw.depth + 15
        claw.depth = byte(d)
        done = d >= FAR
        }
    if (done) {
        this.phase = "lifeLost"
        for (const s of [...field.shots, ...field.enemyShots]) s.inPlay = false
        this.shotsFlying = 0; this.enemyShotsFlying = 0
        this.nymphsLeft = Math.min(byte(this.onLanes + this.atRim + this.nymphsLeft), 63)
        }
    return
    }
if (claw.dropping) return
if (this.nymphsLeft == 0 && this.blastsGoing == 0) {
    const busy = field.enemies.slice(0, this.level.enemySlots).some((e) => e.inPlay && e.depth >= 0x11)
    if (!busy) {
        this.startDrop(field)
        for (const s of [...field.shots, ...field.enemyShots]) s.inPlay = false
        this.shotsFlying = 0; this.enemyShotsFlying = 0
        }
    }

if (this.playing) {
    if (this.zapLocked) this.zapLocked = false
    else if (this.zapTime == 0) {
        if (field.claw.alive && this.pressed.includes("zap")) {
            if (this.zapsUsed < 2) { this.zapsUsed = this.zapsUsed + 1; this.zapTime = 1 }
            this.pressed = this.pressed.filter((p) => p != "zap")
            }
        }
    else {
        this.zapTime = this.zapTime + 1
        if (this.zapTime >= [0, 19, 5, 0, 0][this.zapsUsed]) this.zapTime = 0
        this.zapOne(field)
        }
    }
this.pressesHeard = true

if (this.zapTime < 3 || this.zapTime % 2 != 0) return
for (let i = this.level.enemySlots - 1; i >= 0; i--) {
    const e = field.enemies[i]
    if (e.inPlay) { e.cargo = "none"; this.destroy(field, e); return }
    }
this.zapTime = 0

if (this.stars == "none") return
let any = 0
for (let i = 7; i >= 0; i--) {
    let d = field.stars[i]
    if (d != 0) {
        d = d - 7
        if (d < RIM) d = this.stars == "growing" ? FAR : 0
        }
    else if (this.stars == "growing") {
        const after = field.stars[(i + 1) % 8]
        if (after != 0) d = after < 0xd5 ? FAR : 0
        }
    field.stars[i] = d
    any = any | d
    }
if (any == 0) this.stars = "none"

if (was == null) { this.set(path, now); return }
const a = now, b = was
for (const key of Object.keys(a)) if (a[key] !== b[key]) this.set([...path, key], a[key])

for (const e of field.enemies) { e.inPlay = false; e.depth = 0 }
this.game.onLanes = 0; this.game.atRim = 0
this.game.kindCount = noneOfEach()

for (const n of field.nymphs) n.rise = 0
if (this.game.nymphsLeft == 0) { this.game.random(1); return }
for (let i = this.game.nymphsLeft - 1; i >= 0; i--) {
    const lane = this.game.random(1) & 15
    const rise = ((i << 4) & 255) | lane
    field.nymphs[i] = { id: i, lane, rise: rise == 0 ? 15 : rise }
    }

let held = this.game.onLanes + this.game.atRim > this.game.level.enemySlots - 1 || this.game.zapTime != 0 || this.game.zapLocked
const near = new Set()
for (let i = 63; i >= 0; i--) {
    const n = field.nymphs[i]
    if (n.rise == 0) continue
    if (!held) {
        n.rise = n.rise - 1
        if (n.rise == 0) { if (!this.surface(field, n)) held = true }
        else if (n.rise == 0x3f && near.has(this.mirrored(n.lane))) n.rise = 0x40
        }
    if (n.rise >= 0x40) { if (this.game.frame % 2 == 0) n.lane = (n.lane + 1) & 15 }
    else if (n.rise >= 0x20) near.add(this.mirrored(n.lane))
    }

const k = this.chooseKind(field, n.lane)
if (k != null && this.launch(field, FAR, n.lane, k)) {
    this.game.nymphsLeft = this.game.nymphsLeft - 1
    n.rise = 0
    return true
    }
n.rise = 1
return false

const lv = this.game.level
const allowed = { flipper: lv.flippers, pulsar: lv.pulsars, tanker: lv.tankers, spiker: lv.spikers,
    fuseball: lv.fuseballs }
const count = this.game.kindCount
const room = noneOfEach()
for (const k of this.kinds) if (allowed[k].max >= count[k]) room[k] = allowed[k].max - count[k]
for (let i = lv.enemySlots - 1; i >= 0; i--) {
    const e = field.enemies[i]
    if (e.inPlay && e.cargo != "none") { const k = this.cargoKind(e.cargo); room[k] = (room[k] + 254) % 256 }
    }
const free = (lv.enemySlots - this.kinds.reduce((n, k) => n + count[k], 0) + 256) % 256
for (const k of this.kinds) if (free < room[k]) room[k] = free
const open = this.kinds.filter((k) => room[k] != 0).length
if (open == 0) return null
const lastFirst = [...this.kinds].reverse()
if (open == 1) {
    for (const k of lastFirst) {
        if (room[k] != 0 && allowed[k].min != 0) { const l = this.launchOf(k, room, lane); if (l != null) return l }
        }
    return null
    }
for (const k of lastFirst) {
    if (room[k] != 0 && count[k] < allowed[k].min) { const l = this.launchOf(k, room, lane); if (l != null) return l }
    }
if (room.spiker != 0 && room.tanker != 0) {
    const l = this.launchOf(this.spikeTip(field, lane) < 0xcc ? "tanker" : "spiker", room, lane)
    if (l != null) return l
    }
let i = (this.game.random(2) & 3) + 1           // from a random kind, pulsar to fuseball, back round the kinds
let tries = 4
do {
    const k = this.kinds[i]
    if (allowed[k].min != 0 && room[k] != 0) {
        const l = this.launchOf(k, room, lane)
        if (l != null) return l
        tries = this.lastTankerTry           // the arcade's loop counter is lost in a failed tanker
        }
    i = i == 0 ? 4 : i - 1
    tries = tries - 1
    } while (tries >= 0)
return null

const lv = this.game.level
if (k == "flipper") return { kind: "flipper", turning: "cw", cargo: "none", fires: true, plan: this.planStart(lv.flipperPlan) }
if (k == "pulsar") return { kind: "pulsar", turning: "cw", cargo: "none", fires: lv.pulsarsFire, plan: "pulsar" }
if (k == "spiker") return { kind: "spiker", turning: "cw", cargo: "none", fires: true, plan: "spiker" }
if (k == "fuseball") return { kind: "fuseball", turning: "cw", cargo: "none", fires: false, plan: "fuseball" }
const r = this.game.random(1) & 3
let c = r
for (let n = 3; n >= 0; n--) {
    c = c == 0 ? 3 : c - 1
    const cargo = lv.tankerCargo[c]
    if (room[this.cargoKind(cargo)] != 0)
        return { kind: "tanker", turning: "cw", cargo, fires: true, plan: "climb" }
    }
this.lastTankerTry = r
return null

for (let i = this.game.level.enemySlots - 1; i >= 0; i--) {
    const e = field.enemies[i]
    if (e.inPlay) continue
    let at = lane
    if (at == 15 && this.game.well.open) at = this.game.random(1) & 14
    field.enemies[i] = { ...e, inPlay: true, kind: l.kind, depth, lane: at, flipping: false, angle: 0,
        turning: l.turning, rising: true, cargo: l.cargo, fires: l.fires, fireWait: 0, resting: false, plan: l.plan }
    this.game.onLanes = this.game.onLanes + 1
    this.game.kindCount = { ...this.game.kindCount, [l.kind]: this.game.kindCount[l.kind] + 1 }
    return true
    }
return false

if (field.claw.alive) {
    for (let i = this.game.level.enemySlots - 1; i >= 0; i--) if (field.enemies[i].inPlay) this.act(field, i)
    }
this.beat(field)

const was = this.game.pulseOn
this.game.pulse = this.game.pulse + this.game.pulseStep
if (this.game.pulseOn != was) {
    if (!this.game.pulseOn) this.game.sound("pulseOff")
    else if (this.game.kindCount.pulsar != 0 && field.claw.alive) this.game.sound("pulseOn")
    }
if (this.game.pulse >= 15 || this.game.pulse <= -64) this.game.pulseStep = -this.game.pulseStep

const e = field.enemies[i]
for (let steps = 0; ; steps++) {
    if (steps == 64) throw new Error(`enemy ${i}'s plan "${e.plan}" never ends its frame`)
    if (!this.stepOf(field, e)) return
    if (field.enemies[i] !== e || !e.inPlay) return       // killed, its slot perhaps taken
    }

switch (e.plan) {

    // climb: up a lane, every frame
    case "climb":
        return this.climbing(field, e, "climb")

    // climbThenFlip: eight frames of climbing, then a flip to the next lane, and again
    case "climbThenFlip":
        e.count = 8
        return this.climbing(field, e, "climbThenFlip.counting")
    case "climbThenFlip.counting":
        e.count = byte(e.count - 1)
        if (e.count != 0) return this.climbing(field, e, "climbThenFlip.counting")
        this.startFlip(field, e); e.plan = "climbThenFlip.flipping"; return false
    case "climbThenFlip.flipping":
        if (this.flipStep(field, e)) { e.plan = "climbThenFlip"; return true }
        return false

    // spiral: climbs while flipping, lane after lane
    case "spiral":
        return this.climbing(field, e, "spiral.flip")
    case "spiral.flip":
        this.startFlip(field, e); e.plan = "spiral.flipping"; return false
    case "spiral.flipping": {
        const done = this.flipStep(field, e)
        if (this.redirected(e, this.move(field, e))) return true
        if (done) return this.climbing(field, e, "spiral.flip")
        return false
        }

    // spiralBack: two flips one way, three the other, climbing all the while
    case "spiralBack":
        return this.climbing(field, e, "spiralBack.first")
    case "spiralBack.first":
        e.count = 2; this.startFlip(field, e); e.plan = "spiralBack.flippingA"; return false
    case "spiralBack.flippingA": {
        const done = this.flipStep(field, e)
        if (this.redirected(e, this.move(field, e))) return true
        if (done) e.plan = "spiralBack.nextA"
        return false
        }
    case "spiralBack.nextA":
        e.count = byte(e.count - 1)
        if (e.count != 0) { this.startFlip(field, e); e.plan = "spiralBack.flippingA"; return false }
        this.reverse(e); e.count = 3; this.startFlip(field, e); e.plan = "spiralBack.flippingB"; return false
    case "spiralBack.flippingB": {
        const done = this.flipStep(field, e)
        if (this.redirected(e, this.move(field, e))) return true
        if (done) e.plan = "spiralBack.nextB"
        return false
        }
    case "spiralBack.nextB":
        e.count = byte(e.count - 1)
        if (e.count != 0) { this.startFlip(field, e); e.plan = "spiralBack.flippingB"; return false }
        this.reverse(e)
        return this.climbing(field, e, "spiralBack.first")

    // flipOffSpikes: climbs while beside a spike's length, else flips (rests its first frame)
    case "flipOffSpikes.start":
        e.plan = "flipOffSpikes"; return false
    case "flipOffSpikes":
        if (this.redirected(e, this.move(field, e))) return true
        if (this.besideSpike(field, e)) return false
        this.startFlip(field, e); e.plan = "flipOffSpikes.climbFlip"; return false
    case "flipOffSpikes.climbFlip":
        if (this.redirected(e, this.move(field, e))) return true
        if (this.flipStep(field, e)) { e.plan = "flipOffSpikes"; return false }
        e.plan = "flipOffSpikes.flipping"; return false
    case "flipOffSpikes.flipping":
        e.plan = this.flipStep(field, e) ? "flipOffSpikes" : "flipOffSpikes.flipping"; return false

    // avoid: flips away from the player, then climbs four frames
    case "avoid":
        this.headForPlayer(field, e); this.reverse(e); this.startFlip(field, e)
        e.plan = "avoid.flipping"; return false
    case "avoid.flipping": {
        if (this.redirected(e, this.move(field, e))) return true
        if (this.flipStep(field, e)) { e.count = 4; e.plan = "avoid.after" }
        return false
        }
    case "avoid.after":
        if (this.redirected(e, this.move(field, e))) return true
        e.count = byte(e.count - 1)
        if (e.count != 0) return false
        e.plan = "avoid"; return true

    // at the rim: four frames to catch the player where it is, then flip round after it
    case "rim":
        e.count = 4; this.catchAtRim(field, e); e.plan = "rim.waiting"; return false
    case "rim.waiting":
        e.count = byte(e.count - 1)
        if (e.count != 0) { this.catchAtRim(field, e); return false }
        this.startFlip(field, e); e.plan = "rim.flipping"; return false
    case "rim.flipping":
        e.count = this.game.level.rimFlipSteps
        while (true) {
            if (this.flipStep(field, e)) { e.plan = "rim"; return true }
            e.count = byte(e.count - 1)
            if (e.count == 0) return false
            }

    // spiker: climbs laying its spike; a spiker turned tanker climbs on as one
    case "spiker": {
        const r = this.move(field, e)
        if (this.redirected(e, r)) return true
        if (this.laySpike(field, e)) return this.climbing(field, e, "climb")
        return false
        }

    // fuseball: rises and sinks, and sometimes crosses to the next spoke
    case "fuseball":
        if (this.fuseMove(field, e)) { e.plan = "fuseball.crossing"; return true }
        this.fuseCatch(field, e); return false
    case "fuseball.crossing":
        e.count = 3; this.fuseCatch(field, e); e.plan = "fuseball.counting"; return false
    case "fuseball.counting":
        e.count = byte(e.count - 1)
        if (e.count != 0) { this.fuseCatch(field, e); return false }
        switch (this.fuseballFlipStep(field, e)) {
            case "landed": e.plan = "fuseball"; return true
            case "chasing": e.plan = "fuseball.crossing"; return true
            case "flipping": e.plan = "fuseball.crossing"; return false
            }

    // pulsar: climbs and pulses for a while, then pulses until the pulse fades, then flips toward the player
    case "pulsar":
        e.count = this.game.level.pulsarWait           // (a wait of nought counts round: 256 frames)
        if (this.redirected(e, this.pulsarMove(field, e))) return true
        e.plan = "pulsar.waiting"; return false
    case "pulsar.waiting":
        e.count = byte(e.count - 1)
        if (e.count != 0) {
            if (this.redirected(e, this.pulsarMove(field, e))) return true
            return false
            }
        e.plan = "pulsar.watching"; return true
    case "pulsar.watching":
        if (this.pulseSoon()) {
            if (this.redirected(e, this.pulsarMove(field, e))) return true
            return false
            }
        this.headForPlayer(field, e); this.startFlip(field, e); e.plan = "pulsar.flipping"; return false
    case "pulsar.flipping":
        if (this.flipStep(field, e)) { e.plan = "pulsar"; return true }
        return false
    }
return false

if (r == "rim") { e.plan = "rim"; return true }
if (r == "gone") return true
return false

const p = word(e.depth * 256 + e.depthFraction + speed)
e.depth = p >> 8; e.depthFraction = p & 255
if (e.depth <= field.claw.depth) return this.reachRim(field, e)
if (e.depth < 0x20 && e.cargo != "none") { this.kill(field, e.id); return "gone" }
return ""

e.depth = field.claw.depth
if (e.kind == "pulsar" && this.game.nymphsLeft != 0) { e.rising = !e.rising; return "" }
if (e.flipping) { e.depth = e.depth + 1; return "" }
this.game.onLanes = this.game.onLanes - 1
if (this.game.atRim != 1) this.headForPlayer(field, e)
else {
    let other = null
    for (let i = this.game.level.enemySlots - 1; i >= 0; i--) {
        const o = field.enemies[i]
        if (o.inPlay && o.id != e.id && o.depth == field.claw.depth) { other = o; break }
        }
    e.kind = "flipper"; e.flipping = false
